-- v992: контент курса «Адаптация» — День 5 · Воронка и касания. Сгенерировано gen-academy-adaptation.mjs

INSERT INTO academy_modules (id, course_id, sort, title, intro, gate, active) VALUES
 ($sd$a0000000-0000-0000-0002-000000000005$sd$, $sd$c0000000-0000-0000-0000-000000000002$sd$, 60, $sd$День 5 · Воронка и касания$sd$, $sd$Путь клиента от заявки до оплаты своими словами. Две цепочки касаний, офферы на демо и на продукт, чек-лист КП.$sd$, $sd${"title":"Зачёт дня 5","tasks":["Проговариваешь весь путь клиента от заявки до оплаты своими словами — этапы, касания, кто что делает","Написал три follow-up: «после демо», «думает», «нет ответа» — наставник проверяет по параметрам формулы","Ролёвка: ведёшь клиента от демо до следующего шага с оффером и датой","Произносишь оффер на демо по Д-Ч-Е-Т без бумажки"],"result":"Понимаешь механику продаж, а не действуешь хаотично."}$sd$::jsonb, true)
ON CONFLICT (id) DO UPDATE SET course_id = EXCLUDED.course_id, sort = EXCLUDED.sort, title = EXCLUDED.title, intro = EXCLUDED.intro, gate = EXCLUDED.gate, active = EXCLUDED.active;

INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000501$sd$, $sd$a0000000-0000-0000-0002-000000000005$sd$, 10, $sd$Цепочка №1: до демо (КЭВ)$sd$, $sd$15 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"Сколько касаний в цепочке до демо?","options":["3","5","7","10"],"correct":2},{"q":"Какой параметр закрывает касание «есть пилотные тарифы»?","options":["Доверие","ЛПР","Финансовая возможность","Здесь и сейчас"],"correct":2},{"q":"Как предлагаем время демо?","options":["Одно время","Два времени: утром и после обеда","«Когда вам удобно?»","Через календарь"],"correct":1},{"q":"Зачем отправляем PDF-кейс Grizzly?","options":["Для красоты","Чтобы клиент показал руководству — выход на ЛПР","Вместо КП","Для отчёта"],"correct":1}]$sd$::jsonb, $sd$<p>Семь касаний, каждое закрывает один параметр формулы решения: осознанная потребность, доверие, ЛПР, финансовая возможность, «здесь и сейчас».</p>
<table class="tbl"><thead><tr><th>#</th><th>Канал</th><th>Параметр</th><th>Шаблон</th></tr></thead><tbody>
<tr><td>1</td><td>Холодный звонок</td><td>Осознанная потребность</td><td>«Вы работаете в дистрибуции, а мы как раз автоматизируем такие компании. Хотите — покажу, как Grizzly увеличили продажи на 30 %»</td></tr>
<tr><td>2</td><td>WhatsApp, текст</td><td>Доверие</td><td>«Спасибо за интерес! В любом случае будет полезно — даже если не начнём работать»</td></tr>
<tr><td>3</td><td>WhatsApp, фото с полей</td><td>Осознанная потребность</td><td>Фото: «Так выглядит аналитика KPI у наших клиентов в реальном времени»</td></tr>
<tr><td>4</td><td>Wazzup</td><td>ЛПР</td><td>«Отправил PDF-кейс по Grizzly: ROI 214 % за 8 месяцев. Можете показать руководству»</td></tr>
<tr><td>5</td><td>Звонок</td><td>Финансовая возможность</td><td>«Есть пилотные тарифы — можно протестировать без больших вложений»</td></tr>
<tr><td>6</td><td>WhatsApp, видео-кружок</td><td>Доверие</td><td>«Записал видео — как торговый оформляет заявку и логист видит маршрут. 40 секунд»</td></tr>
<tr><td>7</td><td>WhatsApp, текст</td><td>Здесь и сейчас</td><td>«Есть окошко на демо в четверг и пятницу — покажу адаптацию под 1С» / «Мы стали партнёрами 2ГИС — покажу на демо, как это работает. Когда удобно?»</td></tr>
</tbody></table>
<ul><li>Кейс и фото подбираются под категорию клиента.</li><li>Предлагаем два времени: одно утром, другое после обеда.</li></ul>$sd$, $sd$[{"t":"Цепочка касаний","u":"https://docs.google.com/spreadsheets/d/1ckgIcp77qnNcQhm0kXyptyuT_GuaSA7j06NgtryyM58/edit"},{"t":"7 касаний до оплаты","u":"https://drive.google.com/file/d/10V-YfE70NK_6qKUJUyehdOjm5L35O57p/view"}]$sd$::jsonb, NULL, NULL, true)
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, sort = EXCLUDED.sort, title = EXCLUDED.title, duration_label = EXCLUDED.duration_label, questions = EXCLUDED.questions, body_html = EXCLUDED.body_html, links = EXCLUDED.links, pass_score = EXCLUDED.pass_score, ack_text = EXCLUDED.ack_text, active = EXCLUDED.active;

INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000502$sd$, $sd$a0000000-0000-0000-0002-000000000005$sd$, 20, $sd$Цепочка №2: после демо до оплаты$sd$, $sd$15 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"Первое касание после демо — это…","options":["Счёт","Фоллоу-ап с резюме встречи: 3 факта и что даёт система","Договор","Звонок директору"],"correct":1},{"q":"Что прикрепляем вторым касанием?","options":["Прайс","Расчёт окупаемости","Презентацию компании","Отзывы"],"correct":1},{"q":"Зачем предлагаем подключить IT-директора или финдиректора?","options":["Чтобы затянуть сделку","Чтобы собрать всех ЛПР — у нас есть презентация под них","Для отчёта","Чтобы получить реквизиты"],"correct":1},{"q":"Через сколько дней после сделки отправляется «текущая ситуация»?","options":["Каждые 20 дней","Каждые 45 дней","Каждые 65 дней","Раз в квартал"],"correct":0}]$sd$::jsonb, $sd$<table class="tbl"><thead><tr><th>#</th><th>Канал</th><th>Параметр</th><th>Шаблон</th></tr></thead><tbody>
<tr><td>1</td><td>WhatsApp, фоллоу-ап</td><td>Осознанная потребность</td><td>«Как обещал — подытожил встречу. 1. У вас 20 пользователей. 2. Работаете в Excel. 3. Потери на логистике ~20 %. Наша система сокращает их на 15–25 %»</td></tr>
<tr><td>2</td><td>Wazzup, расчёт ROI</td><td>Финансовая возможность</td><td>«Прикрепляю расчёт окупаемости: $1 000 на внедрение, $800 экономии в месяц = окупаемость 3,75 месяца»</td></tr>
<tr><td>3</td><td>WhatsApp, аудио</td><td>Доверие</td><td>«Спасибо, что уделили время — классно пообщались. Видно, что вы реально хотите прокачать систему»</td></tr>
<tr><td>4</td><td>WhatsApp, снятие возражения</td><td>Доверие</td><td>«Часто говорят „у нас уже внедрено“ — мы как раз усиливаем текущую систему. Вот 3 примера»</td></tr>
<tr><td>5</td><td>Звонок</td><td>ЛПР</td><td>«Может, стоит подключить IT-директора или финдиректора? Есть отдельная презентация под них»</td></tr>
<tr><td>6</td><td>WhatsApp</td><td>Здесь и сейчас / доверие</td><td>«Сейчас внедряем похожие кейсы до конца месяца — хотим успеть ваш до сезонной загрузки» / новость про партнёрство с 2ГИС</td></tr>
<tr><td>7</td><td>WhatsApp, бонус</td><td>Здесь и сейчас</td><td>«Если решите до пятницы — добавим модуль прогноза спроса бесплатно (обычно +$500)» / «включим поддержку настройки базы 2ГИС бесплатно»</td></tr>
</tbody></table>
<h4>Три follow-up, которые сдаёшь на зачёте</h4>
<ul>
<li><b>«После демо»</b> — резюме: 3 факта о клиенте + что система даёт + следующий шаг с датой.</li>
<li><b>«Думает»</b> — помощь в размышлении: чек-лист сравнения или расчёт, без давления, с бонусом до даты.</li>
<li><b>«Нет ответа»</b> — нейтральный вход + польза (кейс, новость 2ГИС) + два варианта следующего шага.</li>
</ul>
<h4>Повторные продажи — автозадачи после сделки</h4>
<p>Каждые 20 дней — текущая ситуация; каждые 45 — новости и события; каждые 65 — видеоматериалы; каждый квартал — отчётность по периоду.</p>$sd$, $sd$[{"t":"Цепочка касаний","u":"https://docs.google.com/spreadsheets/d/1ckgIcp77qnNcQhm0kXyptyuT_GuaSA7j06NgtryyM58/edit"}]$sd$::jsonb, NULL, NULL, true)
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, sort = EXCLUDED.sort, title = EXCLUDED.title, duration_label = EXCLUDED.duration_label, questions = EXCLUDED.questions, body_html = EXCLUDED.body_html, links = EXCLUDED.links, pass_score = EXCLUDED.pass_score, ack_text = EXCLUDED.ack_text, active = EXCLUDED.active;

INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000503$sd$, $sd$a0000000-0000-0000-0002-000000000005$sd$, 30, $sd$Офферы: на демо и на продукт$sd$, $sd$15 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"ODC — это…","options":["Offer, Deadline, Call to action","Order, Delivery, Contract","Open, Discuss, Close","Оффер, Демо, Цена"],"correct":0},{"q":"Что такое 4U?","options":["Четыре пользователя","Полезность, специфика, срочность, уникальность","Четыре этапа внедрения","Четыре касания"],"correct":1},{"q":"Сколько длится демо по офферу?","options":["10 минут","30 минут","1 час","2 часа"],"correct":1},{"q":"Условие оффера «запуск за 7 дней»:","options":["Только для A-сегмента","Если интеграция не требуется","Только с предоплатой","Только в декабре"],"correct":1}]$sd$::jsonb, $sd$<p>Оффер — не описание продукта, а конкретное предложение с результатом, сроком и причиной действовать сейчас. Три методики.</p>
<h4>Оффер на КЭВ (демо-встречу)</h4>
<ul>
<li><b>ODC</b> (Offer–Deadline–Call to action): «Посмотрите демо-встречу с основателем, где за 30 минут покажем, как навести порядок в работе торговых агентов и доставщиков. Только до пятницы — разберём именно вашу ситуацию. Забронируйте удобное время.»</li>
<li><b>Результат за N дней без боли:</b> «Поймите за 30 минут, как сократить потери и перестать терять заявки — без скучных презентаций и без давления на решение.»</li>
<li><b>4U</b> (полезность, специфика, срочность, уникальность): «Демо для владельцев дистрибьюторских компаний: за 30 минут покажем, как ускорить заявки, автоматизировать доставку и убрать потери на складе. До конца недели — бонус: чек-лист оценки IT-платформ.»</li>
<li><b>Д-Ч-Е-Т для устного озвучивания:</b> «Давайте проведём демо на 30 минут, чтобы вы увидели, как система устраняет хаос в дистрибуции, и покажем на примерах ваших задач; если поймёте, что это то, что нужно, — согласуем следующие шаги.»</li>
</ul>
<h4>Оффер на продукт (лицензии)</h4>
<ul>
<li><b>ODC:</b> «Автоматизация дистрибуции с запуском за 7 дней без интеграции. В декабре — неограниченное количество веб-пользователей бесплатно на весь срок. Оставить заявку сегодня.»</li>
<li><b>Результат без боли:</b> «Запустите учёт заявок, доставки и логистики за 7 дней — без хаоса внедрения, без долгого онбординга.»</li>
<li><b>Д-Ч-Е-Т:</b> «Давайте запустим вашу команду в системе за 7 дней, если интеграция не требуется, чтобы заявки, доставка и логистика работали без сбоев…»</li>
</ul>
<div class="callout">Бонусы и сроки в офферах (декабрь, «до пятницы») — переменные. Актуальный бонус месяца уточняй у РОПа; таблица бонусов — в цепочке касаний.</div>$sd$, $sd$[{"t":"Офферы на КЭВ","u":"https://docs.google.com/spreadsheets/d/1SF2TUp0toZQR1T_mH9nINK-ZC1MRGwHRlUeVGKRf2K0/edit"},{"t":"Офферы на продукт","u":"https://docs.google.com/spreadsheets/d/1JWpnGx220u4v7hLhIB_q3eq70ckIvTJroFp7ZhHyH3U/edit"}]$sd$::jsonb, NULL, NULL, true)
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, sort = EXCLUDED.sort, title = EXCLUDED.title, duration_label = EXCLUDED.duration_label, questions = EXCLUDED.questions, body_html = EXCLUDED.body_html, links = EXCLUDED.links, pass_score = EXCLUDED.pass_score, ack_text = EXCLUDED.ack_text, active = EXCLUDED.active;

INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000504$sd$, $sd$a0000000-0000-0000-0002-000000000005$sd$, 40, $sd$Чек-лист коммерческого предложения$sd$, $sd$10 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"Чем КП должно отличаться от тарифов?","options":["Ценой","Оно персональное — под задачи и нюансы клиента","Логотипом","Ничем"],"correct":1},{"q":"Чем заканчивается хорошее КП?","options":["Подписью","Постскриптумом","Ценой","Списком модулей"],"correct":1},{"q":"На какой вопрос КП обязано ответить?","options":["Сколько нас человек","«Почему именно наша компания?»","Какой у нас офис","Кто основатель"],"correct":1}]$sd$::jsonb, $sd$<p>КП отправляется в день демо. Перед отправкой — 10 пунктов, 1 балл каждый.</p>
<ol class="rules">
<li>Обращение к клиенту по имени</li>
<li>Предложение отличается от тарифов — оно персональное</li>
<li>Визуально оформлено</li>
<li>Есть заголовок — и это не обращение</li>
<li>Заканчивается постскриптумом</li>
<li>Нет шаблонных канцелярских фраз</li>
<li>Понятно, что предлагается, без «воды»</li>
<li>Каждый аргумент или преимущество раскрыты</li>
<li>Отвечает на вопрос «почему именно наша компания?»</li>
<li>Есть инструкция, что делать клиенту дальше</li>
</ol>
<p>Из CJM: КП должно содержать имя-отчество и нюансы, которые проговорили в разговоре, — иначе клиент думает «прислали не то, что обсуждали».</p>$sd$, $sd$[{"t":"Сборник чек-листов · КП","u":"https://docs.google.com/spreadsheets/d/1JJM7ZK5aHcKlfkBXfotGwovXN6V3R75oN4lFQGznkBg/edit"}]$sd$::jsonb, NULL, NULL, true)
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, sort = EXCLUDED.sort, title = EXCLUDED.title, duration_label = EXCLUDED.duration_label, questions = EXCLUDED.questions, body_html = EXCLUDED.body_html, links = EXCLUDED.links, pass_score = EXCLUDED.pass_score, ack_text = EXCLUDED.ack_text, active = EXCLUDED.active;
